Here's a Python implementation of the DFS algorithm:

```python
class Graph:
    def __init__(self, graph_dict=None, directed=True):
        self.graph_dict = graph_dict or {}
        self.directed = directed
        if not directed:
            self.make_undirected()

    def make_undirected(self):
        for a in list(self.graph_dict.keys()):
            for (b, dist) in self.graph_dict[a].items():
                self.graph_dict.setdefault(b, {})[a] = dist

    def connect(self, A, B, distance=1):
        self.graph_dict.setdefault(A, {})[B] = distance
        if not self.directed:
            self.graph_dict.setdefault(B, {})[A] = distance

    def path_exists(self, node1, node2):
        visited = set()
        stack = [(node1, [node1])]
        while stack:
            (vertex, path) = stack.pop()
            if vertex not in visited:
                visited.add(vertex)
                if vertex == node2:
                    return path
                for next_node in list(self.graph_dict[vertex].keys()) + list(self.graph_dict[vertex].values()):
                    if next_node not in visited:
                        stack.append((next_node, path + [next_node]))
        return False

# Example usage
graph = Graph({
    'A': {'B': 1, 'C': 3, 'D': 7},
    'B': {'A': 1, 'D': 2},
    'C': {'A': 3, 'D': 4},
    'D': {'A': 7, 'B': 2, 'C': 4}
})

# Check if there is a path from 'A' to 'D'
path_exists = graph.path_exists('A', 'D')
print(f"Path from 'A' to 'D': {path_exists}")
```

